export function confidenceWeightedVoting(agentOutputs) {
  const weightedResults = agentOutputs.map(output => {
    return {
      value: output.value,
      confidence: output.confidence
    };
  });
  const aggregatedResult = weightedResults.reduce((acc, curr) => {
    acc.value += curr.value * curr.confidence;
    acc.confidence += curr.confidence;
    return acc;
  }, { value: 0, confidence: 0 });
  aggregatedResult.value /= aggregatedResult.confidence;
  return aggregatedResult.value;
}